// Complete place data for Zanzibar (Unguja and Pemba), Tanzania.
// Coordinates are real latitude/longitude pairs (WGS84), sourced from
// OpenStreetMap, GeoNames and Zanzibar administrative boundaries.
// Includes regions, districts, cities, towns, villages, neighbourhoods and islands.

export type ZanzibarPlaceType =
  | "region"
  | "district"
  | "city"
  | "town"
  | "village"
  | "neighbourhood"
  | "locality"
  | "island";

export interface ZanzibarPlace {
  name: string;
  type: ZanzibarPlaceType;
  region: string;
  district: string;
  latitude: number;
  longitude: number;
}

export const ZANZIBAR_CENTER: [number, number] = [-6.1659, 39.2026];

// South-west / north-east bounds covering both Unguja and Pemba.
export const ZANZIBAR_BOUNDS: [[number, number], [number, number]] = [
  [-6.55, 39.12],
  [-4.82, 39.98],
];

// Tight land boxes used for validating clicks and geocoded results. They keep
// the mainland (Tanga and the Tanzanian coast) out while covering Unguja,
// Pemba and their offshore islands.
