export function isInZanzibar(latitude: number, longitude: number): boolean {
  return ZANZIBAR_LAND_BOUNDS.some(
    ([[south, west], [north, east]]) =>
      latitude >= south && latitude <= north && longitude >= west && longitude <= east,
  );
}

export function zanzibarPlacesInRegion(region: string): ZanzibarPlace[] {
  return ZANZIBAR_PLACES.filter((place) => place.region === region);
}

export function findZanzibarPlace(name: string): ZanzibarPlace | undefined {
  const needle = name.trim().toLowerCase();
  return ZANZIBAR_PLACES.find((place) => place.name.toLowerCase() === needle);
}
